      "id": "long-term-care-ombudsman",
      "name": "State Long Term Care Ombudsman Program",
      "shortName": "Ombudsman Program",
      "tagline": "Free advocacy when your loved one faces problems in nursing homes or assisted living facilities.",
      "programType": "resource",
